package dev.horizonlab.parity;
import com.google.gson.*;import java.io.*;import java.lang.reflect.*;import java.nio.file.*;import java.util.*;
import net.minecraft.world.food.*;import net.minecraft.world.entity.*;import net.minecraft.world.entity.player.Player;import net.minecraft.world.level.*;import net.minecraft.server.level.ServerLevel;import net.minecraft.world.item.*;import net.minecraft.world.item.component.*;import net.minecraft.util.RandomSource;import net.minecraft.world.level.levelgen.XoroshiroRandomSource;import net.minecraft.world.phys.Vec3;import net.minecraft.sounds.*;
/** Actual FoodProperties listener, real stored FoodData and both native RNGs. */
public final class VanillaFoodPropertiesOracle {
 static Object unsafe;static Method allocate;static Field position,exhaustion,timer;
 static Field field(Class<?> c,String n)throws Exception{var f=c.getDeclaredField(n);f.setAccessible(true);return f;}
 static <T>T make(Class<T> c)throws Exception{return c.cast(allocate.invoke(unsafe,c));}
 static int n(JsonObject v,String k){return v.get(k).getAsInt();}
 static float fl(JsonObject v,String k){return Float.intBitsToFloat((int)v.get(k).getAsLong());}
 static long bits(float v){return Integer.toUnsignedLong(Float.floatToIntBits(v));}
 static final class Stop extends RuntimeException{}
 static final class Data{JsonObject f;PrintWriter out;FoodData[] foods;RandomSource[] random;LivingEntity actor;boolean changed;int calls;
  JsonObject config(){return f.getAsJsonObject(changed?"after":"initial");}
  void reset(){try{var c=config();var p=c.getAsJsonArray("position");position.set(actor,new Vec3(p.get(0).getAsDouble(),p.get(1).getAsDouble(),p.get(2).getAsDouble()));for(int i=0;i<2;i++){var v=c.getAsJsonArray("foods").get(i).getAsJsonObject();foods[i].setFoodLevel(n(v,"food"));foods[i].setSaturation(fl(v,"saturation"));exhaustion.setFloat(foods[i],fl(v,"exhaustion"));timer.setInt(foods[i],n(v,"timer"));}if(c.get("reseed").getAsBoolean())for(int i=0;i<2;i++)random[i].setSeed(c.getAsJsonArray("seeds").get(i).getAsLong());}catch(Exception e){throw new AssertionError(e);}}
  void all(){try{out.println("state "+calls+" "+changed+" "+n(config(),"random")+" "+n(config(),"food"));for(int i=0;i<2;i++){var food=foods[i];out.println("food "+i+" "+food.getFoodLevel()+" "+bits(food.getSaturationLevel())+" "+bits(exhaustion.getFloat(food))+" "+timer.getInt(food));}}catch(Exception e){throw new AssertionError(e);}}
  void event(String name){out.println("event "+name);int index=calls++;all();if(index==n(f,"fail"))throw new Stop();if(index==n(f,"mutate")){changed=true;reset();}}
  RandomSource random(){event("random");return random[n(config(),"random")];}
 }
 static final class Actor extends Player{Data d;Actor(){super(null,null);}@Override public GameType gameMode(){return GameType.SURVIVAL;}@Override public boolean isSpectator(){return false;}@Override public boolean isCreative(){return false;}@Override public RandomSource getRandom(){return d.random();}@Override public FoodData getFoodData(){d.event("food-data");return d.foods[n(d.config(),"food")];}}
 static final class Other extends net.minecraft.world.entity.decoration.ArmorStand{Data d;Other(){super(null,null);}@Override public RandomSource getRandom(){return d.random();}}
 static final class Level extends ServerLevel{Data d;Level(){super(null,null,null,null,null,null,false,0L,List.of(),false);}@Override public void playSound(Entity excluded,double x,double y,double z,SoundEvent sound,SoundSource source,float volume,float pitch){if(excluded!=null)throw new AssertionError();int id=sound==SoundEvents.GENERIC_EAT.value()?0:sound==SoundEvents.PLAYER_BURP?1:-1;if(id<0)throw new AssertionError();d.event("sound "+id+" "+source.ordinal()+" "+Long.toUnsignedString(Double.doubleToLongBits(x))+" "+Long.toUnsignedString(Double.doubleToLongBits(y))+" "+Long.toUnsignedString(Double.doubleToLongBits(z))+" "+bits(volume)+" "+bits(pitch));}}
 public static void main(String[] args)throws Exception{net.minecraft.SharedConstants.tryDetectVersion();net.minecraft.server.Bootstrap.bootStrap();var u=Class.forName("sun.misc.Unsafe");unsafe=field(u,"theUnsafe").get(null);allocate=u.getMethod("allocateInstance",Class.class);position=field(Entity.class,"position");exhaustion=field(FoodData.class,"exhaustionLevel");timer=field(FoodData.class,"tickTimer");Path dir=Path.of(args[1]);
 try(var out=new PrintWriter(Files.newBufferedWriter(dir.resolve(args[0]+".txt")));var lines=Files.lines(dir.resolve("inputs.txt"))){for(var line:(Iterable<String>)lines::iterator){var d=new Data();d.f=JsonParser.parseString(line).getAsJsonObject();d.out=out;d.foods=new FoodData[]{new FoodData(),new FoodData()};d.random=new RandomSource[2];for(int i=0;i<2;i++){long seed=d.f.getAsJsonArray("seeds").get(i).getAsLong();d.random[i]=d.f.get("xor").getAsBoolean()?new XoroshiroRandomSource(seed):RandomSource.create(seed);}if(d.f.get("player").getAsBoolean()){var actor=make(Actor.class);actor.d=d;d.actor=actor;}else{var actor=make(Other.class);actor.d=d;d.actor=actor;}var level=make(Level.class);level.d=d;d.reset();d.all();var food=new FoodProperties(n(d.f,"nutrition"),fl(d.f,"saturation"),d.f.get("always").getAsBoolean());var consumable=new Consumable(1,ItemUseAnimation.EAT,SoundEvents.GENERIC_EAT,false,List.of());try{food.onConsume(level,d.actor,ItemStack.EMPTY,consumable);out.println("result ok");}catch(Stop e){out.println("result callback");}d.all();for(int i=0;i<2;i++)out.println("random "+i+" "+d.random[i].nextLong()+" "+d.random[i].nextLong());}
 }}
}
